NOTES={}
IDEAS=[]
def n(r,k,i,decision,why,proposal='',refs='',priority='P2'):
    NOTES[(r,k,i)]={'decision':decision,'why':why,'proposal':proposal,'refs':refs.split() if refs else [],'priority':priority}
def idea(r,k,i,name,effect,why,prereq,limits,refs='',priority='P2',l4=''):
    IDEAS.append({'race':r,'kind':k,'id':i,'name':name,'effect':effect,'why':why,'prereq':prereq,'limits':limits,'refs':refs.split() if refs else [],'priority':priority,'l4':l4})
